(function () {
  'use strict';
  const H=window.OrchardInheritance;
  const G=window.OrchardGuidance;
  const escape=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const ref=(page,section)=>[['inheritance',page,section]];
  G.registerDefinitions({
    construction: {title:'Construction method',aliases:['construction method','construction methods','rule constructor'],plain:'A procedure that can build and check a candidate improvement. It is reusable machinery, rather than a stored answer about one encounter.',math:'The fixed primitive construct-rule proposes LOCAL→GLOBAL, checks 320 count/remainder cases, preserves prior labels and requires strict receiving gain in its witness. It becomes available through qualified fallback acquisition.',refs:ref(16,'Appendix D.4, actual construction-policy behaviour')},
    policy: {title:'Construction policy',aliases:['construction policy','component policy','policy tree'],plain:'An ordered program deciding which available construction procedure to try. Earlier successful procedures keep priority.',math:'Π ::= hold | inquiry | construct-rule | fallback(Π,Π) | compose(K). A fallback invokes its old subtree first, then its new subtree only if the old one has no eligible effect. This grammar and its interpreter are supplied and fixed.',refs:ref(16,'Appendix D.4, representation and execution')},
    fallback: {title:'Fallback extension',aliases:['fallback extension','fallback'],plain:'Add a new procedure behind the old program. The old program remains exactly the first branch and keeps its previous behavior.',math:'Π′=fallback(Π,c). A checked positive witness must reach c, and Π′.old must equal Π structurally. Candidate effects separately satisfy soundness, preservation, access and strict final gain.',refs:ref(4,'Construction policies and policy qualification')},
    capturedbasis: {title:'Captured basis',aliases:['captured basis','immutable capture'],plain:'A fixed copy of the component program that a new combining procedure is allowed to use. Later extensions do not silently change that copy.',math:'K=ComponentProjection(Π_current), captured exactly at acquisition. Projection excludes compositor leaves. A candidate compose(K′) is rejected if K′≠K. The accepted tree is deeply frozen. Structural equality assumes an honest host.',refs:ref(16,'Appendix D.4, captured component policy')},
    internal: {title:'Internal view',aliases:['internal view','internal-view witness'],plain:'Temporarily expose an already retained distinction so a construction procedure can be tested. This does not change the external receiving view or emit an action.',math:'I(s) has the same E, W_b(E), context and authority as s, but construction sees a lawful coordinate superset. With A=FULL, construct-rule gains two labels; the resulting component may support a checked composite in the original coarse state.',refs:ref(16,'Appendix D.4, internal-view compositor')},
    compositor: {title:'Compositor',aliases:['compositor','composite acquisition','composite method'],plain:'A supplied procedure that combines a checked rule change with a checked view change, using a component obtained from the captured policy.',math:'compose(K) enumerates lawful internal views, invokes K for an effective rule component, and checks (view,rule) before (rule,view). Intermediate gain may be zero; the whole transaction must have Δ receiving coverage>0. No intermediate action is emitted.',refs:ref(16,'Appendix D.4 and D.6, enumeration and typed effects')},
    bootstrap: {title:'Clean bootstrap',aliases:['clean bootstrap','empty child'],plain:'Load a checked method into a new working context while leaving its observations, answers, action grants, receipts and archive empty.',math:'Child=(Π_loaded,E=∅,conclusions=∅,receivingGrants=∅,receipts=∅,archive=∅). Import requires matching version, scope and structural binding, replayable qualification and a current scoped load grant.',refs:ref(17,'Appendix D.9, qualification and empty bootstrap')},
    owner: {title:'Scoped load grant',aliases:['scoped load grant','load grant'],plain:'Explicit permission from the local owner to load this version of this method for its stated model. It does not permit receiving actions.',math:'LoadAllowed requires allowed=true, epoch=1, matching policy version, scope and binding. These are supplied local host fields, not signatures. Receiving permission is separate and starts absent.',refs:ref(17,'Appendix D.9, current owner record')},
    round: {title:'Acquisition round',aliases:['acquisition rounds','acquisition round','round budget'],plain:'One charged attempt to acquire an eligible new construction procedure. A failed attempt still counts. Running an already available method does not count as acquiring it.',math:'r increments once per complete bounded acquisition attempt; this toy selects the first eligible candidate. Inherited Π₂→Π₃c uses r=1. Reconstruction uses r=1 for the rule constructor and r=2 for the compositor. Source acquisition, qualification replay and invocation work are reported separately; r is not time or total compute.',refs:ref(17,'Appendix D.10, work accounting and routes')},
    ablation: {title:'Method ablation',aliases:['method ablation','causal reuse','ablation'],plain:'Remove one acquired procedure while holding the model and tools fixed, then restore it. A loss and recovery of performance test whether that procedure mattered.',math:'Compare Π₂, Π₁ (construct-rule removed), restored Π₂ and reconstructed Π₂→Π₃c on matched fresh E and round budgets. An unrelated-enquiry removal control tests specificity; direct-search and preinstalled-composite controls bound necessity claims.',refs:ref(6,'Results and causal interventions')},
    artifactbinding: {title:'Structural binding',aliases:['structural binding','artifact binding'],plain:'An exact record tying the loaded method to its current version, model scope and program. A mismatch rejects the load.',math:'B=canonicalJSON({version,scope,policy}). Equality plus qualification replay detects changed local records. This is not a cryptographic digest, issuer authentication or protection against a hostile host.',refs:ref(17,'Appendix D.9; this toy uses structural equality rather than the published manifest digest')},
    transaction: {title:'Repair transaction',aliases:['repair transaction','transaction'],plain:'Check all component changes, then install their combined result once. Intermediate states cannot act.',math:'For each typed step s_i→s_(i+1), E and W_b(E) stay fixed and every decisive old label is preserved. Require lawful view access and sound rules. Final coverage strictly increases. Execution occurs only after final capture and current receiving permission.',refs:ref(16,'Appendix D.6, qualification of typed effects')},
    parentpolicy: {title:'Source and receiving policies',aliases:['Π₁','Π₂','Π₃c'],plain:'Names for the successive programs: supplied enquiry scaffold, scaffold with acquired rule construction, and that program with an acquired combining procedure.',math:'Π₁=fallback(hold,inquiry); Π₂=fallback(Π₁,construct-rule); Π₃c=fallback(Π₂,compose(ComponentProjection(Π₂))). The scaffold is supplied in this toy; source rule construction and receiving composition each have checked positive witnesses.',refs:ref(4,'Construction policies and qualified inheritance')},
    direct: {title:'Direct-search control',aliases:['direct-search control','direct search'],plain:'A conventional supplied search tries the four rule/view combinations directly. It can solve this encounter without acquiring a construction policy.',math:'Enumerate {(LOCAL,COARSE),(GLOBAL,COARSE),(LOCAL,FULL),(GLOBAL,FULL)}; choose a lawful, preserving candidate with positive coverage gain. Acquisition r=0, but candidate and qualification work are nonzero. This is not a universal cost comparison.',refs:ref(6,'Conventional direct-toolbox search control')}
  });

  function run(input) {
    if(!input || input.protocol!=='orchard-lab/1')throw new Error('Unsupported laboratory protocol.');
    const previous=input.previous;
    if(previous && (previous.protocol!=='orchard-lab/1' || previous.experiment!=='coupled-repair' || !previous.passed || !previous.constructionArtifact))throw new Error('Stage two needs the checked source method from the coupled-repair stage.');
    const artifact=previous ? previous.constructionArtifact : H.acquireSource();
    H.validateArtifact(artifact);
    const outputs=H.compare({artifact,permission:true});
    const get=id=>outputs.find(x=>x.route===id);
    const passed=get('intact').decisive===4 && get('removed').decisive===0 && get('restored').decisive===4
      && get('relearn-one').decisive===0 && get('relearn-two').decisive===4 && get('direct').decisive===4;
    return {protocol:'orchard-lab/1',experiment:'qualified-inheritance',passed,
      summary:'Checked method loaded into an empty child. Intact: 4/4 decisions in one acquisition round; removed: 0/4; restored: 4/4; reconstruction: two rounds. Direct search: 4/4 with zero acquisition rounds. All receiving grants are new supplied inputs.',
      previousConsumed:!!previous,transfer:'qualified-construction-policy',evidenceTransfer:'none',authorityExpanded:false,grammarExpanded:false,
      sourceBinding:artifact.binding,emptyBootstrap:get('intact').child,
      comparisons:outputs.map(x=>({route:x.route,decisive:x.decisive,rounds:x.counts.rounds,counts:x.counts}))};
  }

  function mount({container}) {
    const abort=new AbortController(), artifact=H.acquireSource();
    const options={route:'intact',rounds:1,permission:false,access:true,load:true,counterfeit:false,pollution:false};
    let result=null, error=null, stage=0;
    const standard=H.compare({artifact,permission:true});
    const stages=[
      ['A method, rather than an old answer','Milestone one showed a coupled repair. Here we acquire a rule constructor on a full internal view, then ask whether that procedure helps a genuinely fresh receiving encounter. The constructor language and qualifier are supplied.','Next: load an empty child'],
      ['Transfer without old evidence or authority','The source acquires Π₂ through a checked fallback extension. A scoped load grant admits that version into an empty child. Qualification is replayed. The five zero counts below describe the child at load, before new observations arrive.','Next: build a fresh repair'],
      ['Construct with new evidence','Two new contexts provide their own evidence roots. The second reverses the target reports, so old target answers would be wrong. An inherited constructor supplies a component on an internal view; the compositor checks the combined repair for the actual receiver. Receiving permission still starts off.','Next: compare the interventions'],
      ['Remove, restore, reconstruct','Compare the nine matched routes below. Inherited construction needs one acquisition round; reconstruction needs two. Removing unrelated enquiry preserves success. Direct search succeeds with no acquisition, showing that this dependency belongs to the declared policy route.','Next: stress the boundaries'],
      ['Bounded reuse is a step towards MeRSIA','Try a zero round budget, inaccessible bit, revoked receiving permission, invalid captured basis or polluted bootstrap. Each boundary has a different failure reason. The experiment learns within a fixed grammar; enquiry, language change and relative development rate remain later milestones.','Return to the introduction']
    ];
    container.innerHTML=`
      <section class="intro"><div><div class="chapter">Encounter 02 · qualified inheritance</div><h1>Carry the Method Forward</h1><p>A fresh context inherits a way to construct a repair. Remove it, restore it, or rebuild it—and watch what changes under the same evidence and boundaries.</p></div><div class="intro-note">A reusable procedure.<br>New evidence. New permission.<br>Two contexts, four target decisions.</div></section>
      <section class="guided-path" aria-label="Inheritance guided experience"><div class="guide-top"><span class="chapter" id="inherit-guide-count"></span><span class="helper">Click dotted terms for the meaning, mathematics and source.</span></div><div class="guide-steps" id="inherit-guide-steps"></div><h2 id="inherit-guide-title"></h2><p id="inherit-guide-description"></p><div class="guide-actions"><button class="secondary" id="inherit-back" type="button">Previous stage</button><button class="primary" id="inherit-next" type="button"></button><button class="quiet" id="inherit-glossary" type="button">Browse all definitions</button></div></section>
      <section class="panel lineage-panel"><div class="section-heading"><h2>What crosses the boundary?</h2><span class="helper">Source acquisition is one separate, common round</span></div><div class="policy-lineage" id="policy-lineage"></div>
        <div class="bootstrap-strip" aria-label="Empty child at load">${['Observations','Conclusions','Receiving grants','Receipts','Archive'].map(s=>`<div><strong>0</strong><span>${s}</span></div>`).join('')}</div><p>The clean bootstrap transfers only the checked construction policy. These zeros describe the child <strong>before</strong> its new encounter reports arrive. A load grant does not grant receiving permission.</p><details class="trace"><summary>Inspect the source acquisition and scoped record</summary><p>Supplied Π₁ → acquired Π₂. The internal-view witness gains 0 → 2 receiving labels with fixed evidence. The rule qualifier checks 320 abstract cases. The acquisition is replayed at load. Structural binding assumes this honest local host.</p><pre class="policy-code" id="source-record" data-no-terms></pre></details></section>
      <div class="workspace inheritance-workspace"><aside class="controls inheritance-controls" aria-label="Inheritance controls"><div class="control-intro"><h2>Choose a route</h2><p class="helper">Change one dependency, then test its consequences.</p></div>
        <label class="field" for="inherit-route">Construction route<select id="inherit-route">${H.ROUTES.map(r=>`<option value="${r.id}">${escape(r.title)}</option>`).join('')}</select></label>
        <label class="field" for="inherit-rounds">Acquisition round budget<select id="inherit-rounds"><option value="0">0 · invoke existing methods only</option><option value="1" selected>1 · one acquisition attempt</option><option value="2">2 · two acquisition attempts</option></select></label>
        <label class="toggle-row permission-toggle"><span><strong>Current receiving permission</strong><small>Explicit fresh grant for the two toy contexts. Starts off; acquisition cannot turn it on.</small></span><input id="inherit-permission" aria-label="Current receiving permission for inheritance" type="checkbox"></label>
        <div class="control-buttons"><button class="primary wide-button" id="inherit-run" type="button">Run selected route</button><button class="quiet wide-button" id="inherit-reset" type="button">Reset to empty child</button><p class="live-note" id="inherit-live-note">Ready to load the method and supply the new encounters.</p></div>
        <details class="assumptions" id="inherit-stress"><summary>Stress the transfer and repair</summary>
          <label class="checkbox-line"><input id="inherit-load" aria-label="Current scoped load grant" type="checkbox" checked><span>Current scoped load grant</span></label>
          <label class="checkbox-line"><input id="inherit-access" aria-label="Allow exposing the missing coordinate" type="checkbox" checked><span>Allow exposing the missing coordinate</span></label>
          <label class="checkbox-line"><input id="inherit-counterfeit" aria-label="Submit an invalid captured basis" type="checkbox"><span>Submit an invalid captured basis during composite acquisition</span></label>
          <label class="checkbox-line"><input id="inherit-pollution" aria-label="Attempt to inherit an old observation" type="checkbox"><span>Attempt to inherit an old observation at bootstrap</span></label>
          <p class="live-note">The error allowance stays at b=1. These probes vary authority, access and program currentness.</p>
        </details></aside>
        <div class="working-area"><div class="metrics" aria-live="polite"><div class="metric"><div class="metric-name">Decisive receiving labels</div><div class="metric-value" id="inherit-repaired">— / 4</div><div class="metric-detail">Knowledge after the checked repair</div></div><div class="metric"><div class="metric-name">Simulated receiving decisions</div><div class="metric-value" id="inherit-decisions">— / 4</div><div class="metric-detail">Requires fresh current permission</div></div><div class="metric"><div class="metric-name">Acquisition rounds used</div><div class="metric-value" id="inherit-used">— / 1</div><div class="metric-detail">Source acquisition is counted separately</div></div></div>
          <section class="context-map"><div class="map-header"><div><h2>Fresh contexts, freshly checked answers</h2><p id="inherit-context-caption">Run a route to see what the receiver can justify and do.</p></div><span class="map-label">No transferred observations</span></div><div class="fresh-contexts" id="inherit-contexts"><p>Receiving context 1: new roots, target reports safe / harmful.<br>Receiving context 2: new roots, target reports harmful / safe.<br>Compatible worlds per context: 1,073,741,824.</p></div></section>
          <div class="state-explanation" id="inherit-explanation" aria-live="polite"><strong>Ready for a fresh encounter.</strong><p>The matched comparison below is already calculated. Your selected experiment starts with receiving permission off.</p></div>
          <section class="panel research-note"><h2>Work remains visible</h2><p>Acquisition rounds count attempts to add methods. They do not measure total computation. These receiving-route counters include failed probes and repeated qualification.</p><div class="work-counters" id="inherit-work"></div><p class="helper">The common source acquisition checks 320 rule cases; load qualification replays that acquisition separately. Every route also uses the same supplied interpreter and finite model.</p></section>
        </div></div>
      <div class="lower-grid"><section class="panel"><h2>The causal comparison</h2><p>Nine routes share the same two new evidence fixtures, model, access and explicit supplied receiving grants. Each route uses the stated round budget. Green marks your selected route.</p><div class="inheritance-comparison" id="inherit-comparison" role="img" aria-label="Nine matched routes, decisive decisions out of four"></div><div class="axis-note">Bar length: simulated decisive decisions, 0–4. Round counts are receiving acquisition only.</div><p><strong>Direct search also solves the task.</strong> It uses zero acquisition rounds, but still evaluates candidates and qualifies the rule. Inheritance is causal for this policy route; it is not universally necessary.</p></section>
        <section class="panel"><h2>Where does this route become effective?</h2><p id="inherit-frontier-caption"></p><div id="inherit-frontier"></div><div class="axis-note">Horizontal: allowed acquisition rounds (0–2). Vertical: decisive receiving labels (0–4). This plot assumes a valid load and accessible bit.</div><div class="research-claim"><strong>What this establishes</strong><p>Removal, restoration and reconstruction identify a reusable dependency. The new context constructs a repair from its own evidence, while method improvement preserves the earlier policy subtree. This is bounded construction learning in a fixed grammar.</p><p>Changing that grammar or showing that alignment learning outpaces other capabilities requires additional experiments.</p></div></section></div>
      <section class="panel research-note"><h2>One checked transaction, then receiving use</h2><p>A component can have zero gain at the coarse receiver. It must be sound and preserve prior labels. The completed pair must have positive receiving gain. Intermediate states emit no actions.</p><div class="transaction-display" id="inherit-transaction">Run a route to inspect its construction trace.</div><details class="trace"><summary>Inspect the acquisition log and policy tree</summary><div id="inherit-learning"></div><pre class="policy-code" id="inherit-policy" data-no-terms></pre></details></section>
      <section class="panel research-note"><details><summary>Mathematical scope and provenance</summary><div class="note-grid"><div><h3>How it builds on milestone one</h3><p>The finite five-bit evidence and receiving semantics are unchanged. The new experiment supplies the policy grammar, fallback interpreter, internal-view compositor and scoped bootstrap. Rule acquisition and composite acquisition have checked positive witnesses; candidate effects keep evidence and compatible worlds fixed.</p><p>See the inheritance paper, pp. 4–7 and Appendix D, pp. 16–17. Each dotted term links to its source pages.</p></div><div><h3>What this toy includes</h3><p>Two new contexts and four target requests, including reversed target labels. The published experiment describes a larger population; this is an educational reconstruction, not a reproduction of that complete package.</p><p>The initial enquiry scaffold, grammar, qualifiers and comparison fixtures are supplied. There are no model calls, learned new semantics, real external actions or hostile-host security guarantees. The source has one common acquisition round before receiving comparisons.</p></div></div></details></section>`;

    const q=id=>container.querySelector('#'+id);
    const listen=(id,event,fn)=>q(id).addEventListener(event,fn,{signal:abort.signal});
    function describePolicy(p){
      if(p.kind==='fallback')return 'fallback('+describePolicy(p.old)+', '+describePolicy(p.next)+')';
      return p.kind==='compose' ? 'compose(captured '+describePolicy(p.basis)+')' : p.kind;
    }
    function lineage(){
      q('policy-lineage').innerHTML=[['Supplied source','Π₁','Enquiry scaffold; zero enquiry allowance'],['Acquired source','Π₂','Checked rule constructor; +2 witness gain'],['Child at clean load',error ? 'Rejected' : 'Π₂',error ? 'No receiving experiment started' : 'Method only; interventions happen after load'],['Receiving development',result && H.contains(result.policy,'compose') ? 'Π₃c' : 'Pending',result ? result.learning.filter(x=>x.learned).map(x=>x.learned).join(' → ') || 'Invoke available policy; no new acquisition' : 'Construct with new encounter evidence']].map((x,i)=>`<div class="lineage-node"><span>${x[0]}</span><strong>${x[1].startsWith('Π')?`<button type="button" class="term" data-term="parentpolicy" aria-label="Define ${x[1]}" aria-haspopup="dialog">${x[1]}</button>`:x[1]}</strong><small>${x[2]}</small></div>${i<3?'<span class="lineage-arrow" aria-hidden="true">→</span>':''}`).join('');
      q('source-record').textContent=JSON.stringify({version:artifact.version,scope:artifact.scope,qualification:artifact.qualification,sourceAcquisitionRounds:artifact.acquisition.rounds,policy:artifact.policy,bindingType:'canonical structure; qualification replay; honest local host'},null,2);
    }
    function guide(){
      q('inherit-guide-count').textContent='Guided stage '+(stage+1)+' of '+stages.length;
      q('inherit-guide-title').textContent=stages[stage][0];q('inherit-guide-description').textContent=stages[stage][1];
      q('inherit-next').textContent=stages[stage][2];q('inherit-back').disabled=stage===0;
      q('inherit-guide-steps').innerHTML=stages.map((s,i)=>`<button type="button" class="guide-stage ${i===stage?'active':''}" data-stage="${i}" aria-current="${i===stage?'step':'false'}">${i+1} · ${['Method','Empty child','Fresh repair','Causal test','Boundaries'][i]}</button>`).join('');
      if(stage===4)q('inherit-stress').open=true;
    }
    function plots(){
      q('inherit-comparison').innerHTML=standard.map(r=>`<div class="inheritance-row ${r.route===options.route?'current':''}"><span>${escape(H.ROUTES.find(s=>s.id===r.route).title)}</span><div class="bar-track"><div class="bar" style="width:${r.decisive/4*100}%"></div></div><span class="comparison-value">${r.decisive}/4</span><small>${r.counts.rounds} round${r.counts.rounds===1?'':'s'}</small></div>`).join('');
      q('inherit-comparison').setAttribute('aria-label',standard.map(r=>H.ROUTES.find(s=>s.id===r.route).title+': '+r.decisive+' of 4 decisions in '+r.counts.rounds+' acquisition rounds').join('; '));
      const points=[0,1,2].map(rounds=>H.runRoute({artifact,route:options.route,rounds,permission:options.permission}));
      const sx=i=>55+i*135,sy=v=>172-v*32;
      const labels=points.map(p=>p.repaired),actions=points.map(p=>p.decisive);
      q('inherit-frontier-caption').textContent=H.ROUTES.find(r=>r.id===options.route).title+'. Permission '+(options.permission?'on: checked labels can reach simulated action.':'off: labels may become decisive, but actions hold.');
      q('inherit-frontier').innerHTML=`<svg class="frontier-svg" viewBox="0 0 380 230" role="img" aria-label="For acquisition budgets zero, one and two, receiving label counts are ${labels.join(', ')} and permitted action counts are ${actions.join(', ')}"><title>Receiving labels and permitted decisions by acquisition budget</title>${[0,2,4].map(v=>`<line x1="55" y1="${sy(v)}" x2="325" y2="${sy(v)}" stroke="#ccd7e1"/><text x="37" y="${sy(v)+5}" text-anchor="end">${v}</text>`).join('')}<polyline points="${labels.map((v,i)=>sx(i)+','+sy(v)).join(' ')}" stroke="#2359af" fill="none" stroke-width="3"/><polyline points="${actions.map((v,i)=>sx(i)+','+sy(v)).join(' ')}" stroke="#087859" fill="none" stroke-width="3" stroke-dasharray="5 4"/>${labels.map((v,i)=>`<circle cx="${sx(i)}" cy="${sy(v)}" r="5" fill="#2359af"/><text x="${sx(i)}" y="202" text-anchor="middle">${i}</text><text x="${sx(i)}" y="${sy(v)-13}" text-anchor="middle">${v}</text>`).join('')}<text x="55" y="224">Acquisition round budget</text></svg><div class="plot-legend"><span><i class="legend-line"></i>Decisive labels</span><span><i class="legend-line action-line"></i>Permitted decisions</span></div><table class="inspector-table"><caption class="helper">Exact plot values</caption><thead><tr><th>Budget</th><th>Labels</th><th>Decisions</th></tr></thead><tbody>${points.map((p,i)=>`<tr><td>${i}</td><td>${p.repaired}/4</td><td>${p.decisive}/4</td></tr>`).join('')}</tbody></table>`;
    }
    function render(){
      guide();lineage();plots();
      const r=result;
      q('inherit-repaired').textContent=r ? r.repaired+' / 4' : '— / 4';q('inherit-decisions').textContent=r ? r.decisive+' / 4' : '— / 4';
      q('inherit-used').textContent=(r?r.counts.rounds:'—')+' / '+options.rounds;
      q('inherit-live-note').textContent=error ? 'Rejected: '+error : r ? 'Selected route checked. All decisions are local simulations.' : 'Ready to load the method and supply the new encounters.';
      q('inherit-context-caption').textContent=r ? 'The second context reverses target labels. Both keep their own 4 evidence roots and their compatible worlds.' : 'Run a route to see what the receiver can justify and do.';
      q('inherit-contexts').innerHTML=r ? r.contexts.map((x,i)=>`<div class="fresh-context"><h3>Receiving context ${i+1}</h3><p>New root namespace: ${escape(x.id)}<br>Worlds: ${Number(x.worlds).toLocaleString('en-GB')}</p><div class="context-decisions">${x.decisions.map((v,j)=>`<div><span>Case 0${j}</span><strong class="${x.labels[j]===null?'':'warranted'}">${x.labels[j]===null?'Unresolved':x.labels[j]===0?'Safe':'Harmful'}</strong><small>${v.toUpperCase()} · ${x.reason==='permission'?'permission absent':x.labels[j]===null?'no decisive label':'current record'}</small></div>`).join('')}</div></div>`).join('') : '<p>Receiving context 1: new roots, target reports safe / harmful.<br>Receiving context 2: new roots, target reports harmful / safe.<br>Compatible worlds per context: 1,073,741,824.</p>';
      const rejected=r && r.learning.find(x=>x.rejection);
      q('inherit-explanation').innerHTML=error ? `<strong>Load rejected before any receiving experiment.</strong><p>${escape(error)}</p>` : !r ? '<strong>Ready for a fresh encounter.</strong><p>The matched comparison is calculated from fixed fixtures. Your selected test starts with receiving permission off.</p>' : `<strong>${r.repaired===4 ? 'The current method justifies all four target labels.' : 'The receiving gap remains unresolved.'}</strong><p>${r.decisive===4?'Fresh permission admits all four simulated decisions.':r.repaired===4?'Receiving permission is absent: every simulated action holds, despite the justified labels.':escape(rejected ? rejected.rejection : 'No installed policy reaches a positive repair within the selected acquisition budget.')}</p>`;
      q('inherit-work').innerHTML=['candidates','constructorCalls','qualifierCases','componentUses','pairChecks','executionCalls'].map((key,i)=>`<div><strong>${r?r.counts[key]:'—'}</strong><span>${['Acquisition / search candidates','Rule-constructor invocations','Rule qualification cases','Effective component uses','Transaction pair checks','Final receiving checks'][i]}</span></div>`).join('');
      const trace=r && r.contexts[0].trace;
      q('inherit-transaction').innerHTML=trace && trace.length ? `<div class="transaction-steps">${trace.map(x=>`<div><span>Checked ${x.step==='view'?'view refinement':'rule construction'}</span><strong>${x.before} → ${x.after} labels</strong><small>Gain ${x.gain} · intermediate actions ${x.emittedActions}</small></div>`).join('<span class="lineage-arrow" aria-hidden="true">→</span>')}<div><span>Final current receiving gate</span><strong>${r.contexts[0].decisions.join(' / ')}</strong><small>Fresh permission ${r.contexts[0].permission?'on':'off'}</small></div></div><p>Evidence unchanged; world count remains ${Number(r.contexts[0].worlds).toLocaleString('en-GB')}. The final method is reused with new evidence in context 2.</p>` : r ? `<p>${r.contexts[0].method==='supplied-direct-search' ? 'The supplied direct-search control selects a checked final configuration without acquiring a compositor.' : 'No composite transaction reached the receiver in this run.'} No intermediate actions occur.</p>` : 'Run a route to inspect its construction trace.';
      q('inherit-learning').innerHTML=r ? (r.interventions.length ? '<p>Supplied interventions: '+r.interventions.map(x=>x.operation+' '+x.method).join(' → ')+'.</p>' : '')+'<ol>'+r.learning.map(x=>`<li>Round ${x.round}, ${escape(x.context)}: ${x.learned ? 'acquired '+escape(x.learned)+'; positive witness gain '+x.witnessGain : 'no acquisition; '+escape(x.rejection || 'no eligible method')}.</li>`).join('')+'</ol><p>Acquisition budget is shared across the two new contexts; the developed method persists, their observations and receipts do not transfer.</p>' : '<p>No receiving acquisition attempted yet.</p>';
      q('inherit-policy').textContent=r ? describePolicy(r.policy)+'\n\n'+JSON.stringify(r.policy,null,2) : 'At clean load:\n'+describePolicy(artifact.policy);
      G.annotate(container);
    }
    function execute(){
      error=null;result=null;
      try{result=H.runRoute({artifact,...options,owner:H.ownerGrant(artifact,options.load),seed:options.pollution?{observations:[{root:'old-source-observation'}],conclusions:[],receivingGrants:[],receipts:[],archive:[]}:undefined});}
      catch(e){error=e.message;}
      render();
    }
    function changed(){result=null;error=null;render();}
    listen('inherit-route','change',()=>{options.route=q('inherit-route').value;options.rounds=H.ROUTES.find(x=>x.id===options.route).rounds;q('inherit-rounds').value=String(options.rounds);changed();});
    listen('inherit-rounds','change',()=>{options.rounds=Number(q('inherit-rounds').value);changed();});
    for(const [id,key] of [['inherit-permission','permission'],['inherit-access','access'],['inherit-load','load'],['inherit-counterfeit','counterfeit'],['inherit-pollution','pollution']])listen(id,'change',()=>{options[key]=q(id).checked;changed();});
    listen('inherit-run','click',execute);
    listen('inherit-reset','click',()=>{Object.assign(options,{route:'intact',rounds:1,permission:false,access:true,load:true,counterfeit:false,pollution:false});q('inherit-route').value='intact';q('inherit-rounds').value='1';for(const [id,key] of [['inherit-permission','permission'],['inherit-access','access'],['inherit-load','load'],['inherit-counterfeit','counterfeit'],['inherit-pollution','pollution']])q(id).checked=options[key];stage=0;changed();});
    listen('inherit-back','click',()=>{stage=Math.max(0,stage-1);render();});
    listen('inherit-next','click',()=>{stage=(stage+1)%stages.length;if(stage===2)execute();else render();});
    listen('inherit-guide-steps','click',e=>{const b=e.target.closest('[data-stage]');if(b){stage=Number(b.dataset.stage);render();}});
    listen('inherit-glossary','click',()=>G.showGlossary());
    render();
    if(document.modelContext && typeof document.modelContext.registerTool==='function') {
      const noArguments=input=>{if(!input || typeof input!=='object' || Array.isArray(input) || Object.keys(input).length)throw new Error('This action takes an empty object.');};
      const read=()=>({experiment:'qualified-inheritance',options:{...options},error,result});
      const tools=[
        {name:'read_inheritance_encounter',title:'Read inheritance encounter',description:'Read the selected local construction route, current controls and computed results. No state change.',annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){noArguments(input);return read();}},
        {name:'run_inheritance_route',title:'Run selected inheritance route',description:'Run the selected local toy route with existing load grant, access and receiving permission. Never grants permission. No external action.',annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){noArguments(input);q('inherit-run').click();return read();}}
      ];
      for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool({...tool,inputSchema:{type:'object',properties:{},additionalProperties:false}},{signal:abort.signal})).catch(()=>{});}catch{}}
    }
    return {dispose(){abort.abort();},snapshot(){return {options:{...options},result,error,guideStep:stage};}};
  }
  window.OrchardLab.register({id:'qualified-inheritance',title:'02 · Carry the Method Forward',version:'0.2.0',contractVersion:1,mount,run});
})();
